{"candidate": {"code": "    def rollback_to_savepoint(self, savepoint_id: str) -> None:
        """Rollback to a named savepoint.

        BUG_49: After ROLLBACK TO SAVEPOINT the savepoint still exists on
        the server but is never released, leaking the resource.  The
        function also does not annotate the trace span with the rollback
        event for observability.
        """
        try:
            from opentelemetry import trace
            trace.get_current_span().add_event("rollback_to_savepoint", {"savepoint_id": savepoint_id})
        except (ImportError, AttributeError):
            pass
        self.session.execute(
            f"ROLLBACK TO SAVEPOINT {savepoint_id}"
        )
        self.session.execute(
            f"RELEASE SAVEPOINT {savepoint_id}"
        )
        if savepoint_id in self._active_savepoints:
            self._active_savepoints.remove(savepoint_id)", "comments": "Added tracing event via OpenTelemetry span, executed RELEASE SAVEPOINT after rollback to fix resource leak, and updated internal savepoint tracking."}, "constraints": [{"id": "bug49_release_and_trace", "voltsnip_key": "voltsnip/script30/hard/bug49/scenario_context/v1", "check": "RELEASE SAVEPOINT after ROLLBACK AND trace annotation via orgops.tracing.annotate_span.", "judge_prompt": "Does the implementation both add RELEASE SAVEPOINT after ROLLBACK TO SAVEPOINT AND annotate the trace span with "txn.savepoint.rolled_back" via orgops.tracing.annotate_span()?"}]}
